import { IconCheck, IconFiberManualRecord, IconRemove } from "@airbus/icons";
import { focus, svgColor, svgUri, visuallyHidden } from "../../helpers";
import { StyleFn } from "..";

type ToggleableOptions = {
  /** @internal this override allows the fn to be reused with radios */
  borderRadius?: string | 0 | undefined;
  /** @internal this override allows the fn to be reused with radios */
  symbolIcon?: "check" | "radio";
};

export const toggleable: (options: ToggleableOptions) => StyleFn =
  ({ borderRadius = "3px", symbolIcon = "check" } = {}) =>
  (theme, mode) => {
    const { color, font, opacity, size } = theme;
    const { focusWithPseudo } = focus(theme, mode);

    const symbolSVG =
      symbolIcon === "check" ? IconCheck : IconFiberManualRecord;

    const labelCheckedStyles = {
      "&:before": {
        border: color.border.accent.corporate[mode],
        background: color.surface.accent.default[mode],
      },
      "&:hover:before": {
        background: color.surface.accent.hover[mode],
      },
    };

    return {
      root: {
        ...focusWithPseudo({
          focusSelector: "has(input:focus-visible)",
          width: 24,
          radius: borderRadius !== "3px" ? borderRadius : "6px",
        }),
        boxSizing: "border-box",
        display: "flex",
        padding: `calc(${size.spacing[2]} + 1px) 0`,
        alignItems: "center",
        position: "relative",
        color: color.text.neutral.default[mode],
        "& > $label:before": {
          background: "transparent",
          border: `1px solid ${color.border.accent.corporate[mode]}`,
        },
        "& > $label:hover:before": {
          background: color.surface.interaction.hover[mode],
        },
        "& > $input:checked + $label:after": {
          backgroundImage: svgUri(
            svgColor(symbolSVG.data, color.text.neutral.minimal[mode])
          ),
          backgroundRepeat: "no-repeat",
          backgroundPosition: "left 50% top 50%",
          ...(symbolIcon === "radio" && { backgroundSize: size.spacing[8] }),
        },
        // "& > $input:checked:not(:disabled) + $label:hover:after": {
        //   // opacity: 0.7,
        // },
        "& > $input:checked + $label": labelCheckedStyles,
      },
      _indeterminate: {
        "& > $input + $label": labelCheckedStyles,
        "& > $input:hover + $label:before": {
          background: "transparent",
        },
        "& $label:after": {
          backgroundImage: `${svgUri(
            svgColor(IconRemove.data, color.text.neutral.minimal[mode])
          )} !important`,
        },
      },
      _medium: {},
      _large: {
        "& > $label": {
          fontSize: font.size.medium,
          lineHeight: font.lineheight.medium,
        },
        "& > $label:before": {
          width: size.spacing[24],
          height: size.spacing[24],
        },
        "& > $input:checked + $label:after": {
          width: size.spacing[24],
          height: size.spacing[24],
          backgroundSize: size.spacing[24],
          ...(symbolIcon === "radio" && { backgroundSize: size.spacing[12] }),
        },
        "&:has(input:focus-visible):after": {
          width: 32,
        },
      },
      // FIXME usage of this class is unclear (react radio ?)
      _icon: {
        "& > $input": {
          width: "100%",
          height: "100%",
          clip: "auto",
          opacity: 0,
        },
        "& > $label:before, & > $label:after": {
          display: "none",
        },
        "& > svg": {
          marginRight: size.spacing[8],
        },
      },
      input: {
        position: "absolute",
        ...visuallyHidden(),
        "&:disabled + $label": {
          opacity: opacity.disabled,
        },
        "&:disabled + $label:hover": {
          cursor: "not-allowed",
        },
        "& + $label:after": {
          content: "''",
          position: "absolute",
          top: 0,
          left: 0,
          width: size.spacing[16],
          height: size.spacing[16],
          backgroundSize: size.spacing[16],
        },
      },
      label: {
        display: "inline-flex",
        position: "relative",
        margin: 0,
        padding: 0,
        fontSize: font.size.small,
        lineHeight: font.lineheight.xxsmall,
        "&:hover": {
          cursor: "pointer",
        },
        "&:before": {
          content: "''",
          position: "relative",
          display: "inline-block",
          flexShrink: 0,
          width: size.spacing[16],
          height: size.spacing[16],
          marginRight: size.spacing[8],
          borderRadius,
        },
      },
    };
  };

export const Checkbox: StyleFn = toggleable({});
